class Starship {
    constructor(name, maxSpeed) {
        // TODO: Implement basic validation for name and maxSpeed
        // Name must be a non-empty string
        // maxSpeed must be a positive number
        this.name = name;
        this.maxSpeed = maxSpeed;
    }

    // TODO: Make this an "abstract" method. It should throw an error if called directly,
    // indicating that subclasses must implement their own navigation logic.
    navigate(destination) {
        console.log(`${this.name} is navigating to ${destination}.`);
    }

    getDetails() {
        return `${this.name} (Max Speed: ${this.maxSpeed} units)`;
    }
}

class CargoHauler extends Starship {
    constructor(name, maxSpeed, cargoCapacity) {
        super(name, maxSpeed);
        // TODO: Implement validation for cargoCapacity
        // cargoCapacity must be a positive number
        this.cargoCapacity = cargoCapacity;
    }

    // TODO: Override the navigate method to provide specific cargo hauler navigation logic.
