class Starship {
    constructor(name, maxSpeed) {
        if (typeof name !== 'string' || name.trim() === '') {
            throw new Error("Starship name must be a non-empty string.");
        }
        if (typeof maxSpeed !== 'number' || maxSpeed <= 0) {
            throw new Error("Starship maxSpeed must be a positive number.");
        }
        this.name = name;
        this.maxSpeed = maxSpeed;
    }

    navigate(destination) {
        throw new Error("Method 'navigate()' must be implemented by subclasses.");
    }

    getDetails() {
        return `${this.name} (Max Speed: ${this.maxSpeed} units)`;
    }
}

class CargoHauler extends Starship {
    constructor(name, maxSpeed, cargoCapacity) {
        super(name, maxSpeed);
        if (typeof cargoCapacity !== 'number' || cargoCapacity <= 0) {
            throw new Error("CargoHauler cargoCapacity must be a positive number.");
        }
        this.cargoCapacity = cargoCapacity;
    }

    navigate(destination) {
        if (typeof destination !== 'string' || destination.trim() === '') {
            throw new Error("Invalid destination specified.");
        }
        return `${this.name}, a Cargo Hauler, is carefully charting a course to ${destination}.`;
    }

    loadCargo(item) {
        if (typeof item !== 'string' || item.trim() === '') {
            throw new Error("Cannot load an unnamed or empty item.");
        }
        return `${this.name} is loading ${item}. Current cargo capacity: ${this.cargoCapacity}.`;
    }
}

